  synchronizeProvincePosts(state,{initial=true}={}){const provinces=new Set((state.court?.offices||[]).filter(o=>["zhoumu","cishi"].includes(o.office)&&o.grantedTurn>0).map(o=>o.seat||o.province));for(const command of Object.values(state.forceCommand||{}))for(const p of Object.values(command.posts||{}))if(p.courtProvince)provinces.add(p.courtProvince);for(const province of provinces)this.synchronizeProvincePost(state,province,{initial})},
